  "claims": [
    {
      "claim": "Transferable lipophilic-amine reference contexts report absolute or systemic oral bioavailability well above 20 percent: urapidil 72 to 78 percent, diphenhydramine 69 percent, donepezil about 100 percent, imipramine-N-oxide 100 percent, and tiracizine 34 percent.",
      "card_ids": ["C01","C03","C05","C07","C08","C13","C15","C20"]
    },
    {
      "claim": "L2 records from the same high-F contexts are consistent: urapidil 72 percent delayed-release and over 70 percent in animals, diphenhydramine 0.69 fasted, donepezil about 100 percent, and imipramine-N-oxide 100 percent.",
      "card_ids": ["C21","C22","C27","C30","C33"]
    },
    {
      "claim": "L3 oral exposure records for related tricyclic-like amines show measurable systemic AUC after oral dosing, including desipramine AUC0-inf 655 ng h per mL and imipramine AUC0-inf 427 ng h per mL.",
      "card_ids": ["C34","C37","C38","C43","C45"]
    },
    {
      "claim": "L4 human absorption records for imipramine report essentially 100 percent oral absorption and Fa 100 percent, while related lipophilic amines show favorable solubility.",
      "card_ids": ["C47","C48","C51","C52","C56"]
    },
    {
      "claim": "L5 Caco-2 records for imipramine and desipramine show high permeability and low efflux ratios, with imipramine efflux ratio 1.1 and desipramine permeability about 1e-5 cm per s or higher, indicating no major gut-wall efflux barrier for this amine class.",
      "card_ids": ["C61","C63","C65","C67","C69"]
    },
    {
      "claim": "The only sub-20 percent records are species-specific or structurally dissimilar, such as cat benazeprilat 3.2 percent, rat FK788 9.6 percent, and moexipril 13 to 22 percent, and do not affirm F below 20 percent for the query.",
      "card_ids": ["C24","C25","C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C58","C59","C60","C61","C62","C63","C64","C65","C66","C67","C68","C69"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "No matched oral versus intravenous exposure data are available for the query.",
    "L5 records are for reference molecules, not the query, and no direct gut-wall metabolism measurement exists for the query.",
    "The exact first-pass metabolism of the query is not experimentally confirmed.",
    "Structural analogy to imipramine and desipramine is qualitative."
  ],
  "decision_summary": "Predicted high because the most transferable lipophilic-amine reference contexts consistently report F above 20 percent, L2 records reinforce this pattern, L3 shows measurable oral exposure, L4 shows high absorption and solubility, and L5 shows high Caco-2 permeability with low efflux for related amines. Low-F records are species-specific or structurally dissimilar. No affirmative evidence supports F below 20 percent, so unresolved uncertainty is expressed as moderate confidence."
}

